package com.bank.annotations;

import java.math.BigDecimal;
import java.util.logging.Logger;

// Marked as a runtime component: the MiniContainer will discover this class
// by reflection, exactly the way Spring discovers an @Service.
@RuntimeComponent
public class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());

    // Marked for compile-time auditing: our annotation processor will see this
    // method during compilation and report a note, proving the SOURCE path.
    @CompileAudit
    public void transfer(Account from, Account to, BigDecimal rentAmount) {
        from.debit(rentAmount);
        to.credit(rentAmount);
        log.info(() -> "Transfer " + rentAmount + " from " + from.getAccountId()
                + " to " + to.getAccountId() + " SUCCESS");
    }
}
