package com.bank.annotations;

import java.util.*;
import java.util.logging.Logger;

// A tiny Spring-style container. It receives candidate classes, checks each one
// for the RUNTIME marker using reflection, and builds a single instance (bean).
public class MiniContainer {
    private static final Logger log = Logger.getLogger(MiniContainer.class.getName());
    private final Map<Class<?>, Object> beans = new HashMap<>();

    public void scan(List<Class<?>> candidates) {
        for (Class<?> c : candidates) {
            // isAnnotationPresent only works because RuntimeComponent is RUNTIME-retained.
            if (c.isAnnotationPresent(RuntimeComponent.class)) {
                try {
                    Object bean = c.getDeclaredConstructor().newInstance();
                    beans.put(c, bean);
                    log.info(() -> "Registered bean: " + c.getSimpleName());
                } catch (ReflectiveOperationException e) {
                    log.severe("Failed to create bean for " + c.getName());
                }
            } else {
                log.fine(() -> "Skipped (no @RuntimeComponent): " + c.getSimpleName());
            }
        }
    }

    @SuppressWarnings("unchecked")
    public <T> T getBean(Class<T> type) { return (T) beans.get(type); }

    public int beanCount() { return beans.size(); }
}
