package com.bank.annotations;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.*;

public class AnnotationScanDemo {
    private static final Logger log = Logger.getLogger(AnnotationScanDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        // Spring-style discovery: hand the container a list of candidate classes.
        MiniContainer container = new MiniContainer();
        container.scan(List.of(TransferService.class, Account.class));
        log.info(() -> "Beans discovered by reflection scan: " + container.beanCount());

        // The scanned bean is used without us ever calling 'new TransferService()'.
        TransferService service = container.getBean(TransferService.class);
        BigDecimal rentAmount = new BigDecimal("50000");
        service.transfer(rajesh, priya, rentAmount);

        log.info(() -> "Rajesh balance now: " + rajesh.getBalance());
        log.info(() -> "Priya balance now: " + priya.getBalance());
    }
}
