package com.bank.annotations.processor;

import javax.annotation.processing.*;
import javax.lang.model.SourceVersion;
import javax.lang.model.element.*;
import javax.tools.Diagnostic;
import java.util.Set;

// A real javax.annotation.processing.Processor. javac loads and runs this during
// compilation. It reads SOURCE-retained @CompileAudit markers and reports a note,
// proving the compile-time path is entirely separate from runtime reflection.
@SupportedAnnotationTypes("com.bank.annotations.CompileAudit")
@SupportedSourceVersion(SourceVersion.RELEASE_17)
public class AuditAnnotationProcessor extends AbstractProcessor {
    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        for (TypeElement ann : annotations) {
            for (Element e : roundEnv.getElementsAnnotatedWith(ann)) {
                processingEnv.getMessager().printMessage(
                        Diagnostic.Kind.NOTE,
                        "Compile-time audit found money method: " + e.getSimpleName(), e);
            }
        }
        return true; // we consumed these annotations
    }
}
